package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var TempRecVar TempRec

var tempFile *os.File
var tempReader *bufio.Scanner
var tempOpened bool

func fitS9_3V99(v decimal.Decimal) decimal.Decimal {
	r := v.Round(2)
	neg := r.Sign() < 0
	mag := r.Abs()
	scaled := mag.Shift(2).Round(0).IntPart()
	scaledMod := scaled % 100000
	res := decimal.New(scaledMod, -2)
	if neg && scaledMod != 0 {
		res = res.Neg()
	}
	return res
}

func formatZZ9_9(v decimal.Decimal) string {
	t := v.Truncate(1)
	neg := t.Sign() < 0
	mag := t.Abs()
	scaled := mag.Shift(1).Round(0).IntPart()
	intPart := (scaled / 10) % 1000
	fracPart := scaled % 10
	if fracPart < 0 {
		fracPart = -fracPart
	}
	s := fmt.Sprintf("%03d", intPart)
	bs := []byte(s)
	for i := 0; i < 2; i++ {
		if bs[i] == '0' {
			bs[i] = ' '
		} else {
			break
		}
	}
	_ = neg
	return string(bs) + "." + fmt.Sprintf("%01d", fracPart)
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	t := v.Truncate(2)
	neg := t.Sign() < 0
	mag := t.Abs()
	scaled := mag.Shift(2).Round(0).IntPart()
	intPart := (scaled / 100) % 1000
	fracPart := scaled % 100
	s := fmt.Sprintf("%03d", intPart)
	bs := []byte(s)
	for i := 0; i < 2; i++ {
		if bs[i] == '0' {
			bs[i] = ' '
		} else {
			break
		}
	}
	sign := ' '
	if neg {
		sign = '-'
	}
	return string([]byte{byte(sign)}) + string(bs) + "." + fmt.Sprintf("%02d", fracPart)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseF(field string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(field); i++ {
		c := field[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return decimal.New(n, -1)
}

func READPARA() {
	if !tempReader.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := tempReader.Text()
	// strip trailing \r if present
	if strings.HasSuffix(line, "\r") {
		line = strings.TrimSuffix(line, "\r")
	}
	// line sequential: record is line content; pad/truncate to 8
	rec := padRight(line, 8)
	if len(rec) > 8 {
		rec = rec[:8]
	}
	TempRecVar.TcSensor = rec[0:4]
	TempRecVar.TcF = parseF(rec[4:8])
}

func PROCESSPARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	tmp := TempRecVar.TcF.Sub(decimal.NewFromInt(32)).Mul(decimal.NewFromInt(5))
	q := tmp.Div(decimal.NewFromInt(9))
	r := q.Round(2)
	WsC = fitS9_3V99(r)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(TempRecVar.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Fprint(os.Stdout, padRight(TempRecVar.TcSensor, 4)+" "+WsFEd+"F "+WsCEd+"C\n")
	READPARA()
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	tempFile = f
	tempReader = bufio.NewScanner(f)
	tempReader.Buffer(make([]byte, 1024*1024), 1024*1024)
	tempOpened = true
	READPARA()
	for !(WsEofFlag == "Y") {
		PROCESSPARA()
	}
	f.Close()
	tempOpened = false
	fmt.Fprint(os.Stdout, "READINGS: "+fmt.Sprintf("%02d", WsCount)+" BELOW ZERO: "+fmt.Sprintf("%02d", WsFreeze)+"\n")
}

func main() {
	MAINPARA()
}
